insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('3fe1c8c3-c46f-4a3b-a577-b8ff116c9617', 'N5', '今 ～時～分です', 'Nói/hỏi giờ hiện tại: Bây giờ là ...giờ...phút', '時 đếm giờ, ふん／ぷん đếm phút; 半 = rưỡi', '① Số đếm + 時 (giờ) ② Số đếm + ふん／ぷん (phút) ③ 半(rưỡi)／午前(sáng)／午後(chiều)／夜(tối) + giờ', 'Nói hoặc hỏi thời điểm hiện tại theo giờ/phút, có thể thêm 半/午前/午後/夜 để rõ nghĩa', NULL, '半 = giờ rưỡi; 午前 = buổi sáng (AM); 午後 = buổi chiều (PM); 夜 = buổi tối.', NULL, '{}', NULL, 34, '今 ～時～分です', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('57dc0af9-fcde-430e-abe4-f3aef7bcce27', 'N5', 'N(thứ) は ～曜日です', 'Nói/hỏi thứ trong tuần', '曜日 = thứ (trong tuần)', '今日／N(ngày) + は + ～曜日 + です', 'Nói hoặc hỏi 1 ngày là thứ mấy trong tuần', NULL, NULL, NULL, '{}', NULL, 34, 'N(thứ) は ～曜日です', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('1a9743c4-3fc3-4410-9acf-935b790ccd34', 'N5', '動詞ます形（現在・過去）', 'Thì hiện tại/tương lai và quá khứ của động từ dạng ます', 'ます=hiện tại(+); ません=hiện tại(-); ました=quá khứ(+); ませんでした=quá khứ(-)', NULL, NULL, 'lịch sự (thể ます)', NULL, NULL, '{}', NULL, 34, '動詞ます形（現在・過去）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('98416a06-995f-4ef8-b1fd-026aa40d6abd', 'N5', '何時に Vますか', 'Làm gì vào lúc mấy giờ', 'に đánh dấu thời điểm chính xác (giờ, ngày, tháng...)', '何時 + に + Vますか', 'Hỏi thời điểm chính xác (giờ) xảy ra hành động', NULL, NULL, NULL, '{}', NULL, 35, '何時に Vますか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('c3ef7665-38bb-4b7c-83e5-a5c51cef1cd6', 'N5', '何時から何時まで／何曜日から何曜日まで', 'Từ mấy giờ đến mấy giờ／Từ thứ mấy đến thứ mấy', 'から=từ, まで=đến', '(Thời gian/thứ) + から + (thời gian/thứ) + まで', 'Chỉ khoảng thời gian bắt đầu và kết thúc', NULL, NULL, NULL, '{}', NULL, 35, '何時から何時まで／何曜日から何曜日まで', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('2b3c8291-13bd-434d-a92b-3dbfa33f4fa3', 'N5', 'N は何年／何月／何日ですか', 'Hỏi năm／tháng／ngày bao nhiêu', '何年=năm nào, 何月=tháng nào, 何日=ngày nào', 'N + は + 何年／何月／何日 + ですか', 'Hỏi thời điểm theo năm/tháng/ngày', NULL, 'Lưu ý cách đếm đặc biệt trong tháng và ngày (không phải mọi số đều đọc theo quy tắc chung).', NULL, '{}', NULL, 35, 'N は何年／何月／何日ですか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('2c69e6c2-7c84-4530-9d68-3396cb7c6d5c', 'N5', '(Địa điểm) へ(に) + 行きます／来ます／帰ります', 'Đi đâu／Đến đâu／Về đâu', 'へ hoặc に đều được dùng để chỉ hướng đến', '(Địa điểm) + へ／に + 行きます(đi)／来ます(đến)／帰ります(về)', 'Chỉ hướng di chuyển tới 1 địa điểm', NULL, NULL, NULL, '{"どこ(へ)もいきません"}', NULL, 35, '(Địa điểm) へ(に) + 行きます／来ます／帰ります', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('001cd48a-2590-4a3c-9bf7-5b84ad1c356f', 'N5', 'どこ(へ)もいきません', 'Không đi đâu cả', 'も + phủ định sau どこ = không...đâu cả', 'どこ(へ) + も + いきません', 'Phủ định toàn bộ, nghĩa là không đi bất kỳ đâu', NULL, NULL, 'Khác với どこかへ行きます (đi đâu đó) — どこも luôn đi kèm thể phủ định.', '{"(Địa điểm) へ(に) + 行きます／来ます／帰ります"}', NULL, 35, 'どこ(へ)もいきません', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('4f4df88e-135b-448b-bc56-9738de140aa7', 'N5', 'なにで／どうやって [V di chuyển] か', 'Hỏi đi bằng phương tiện gì', 'なにで hỏi thẳng phương tiện; どうやって hỏi cách thức chung', 'なにで + V(di chuyển) + か ／ どうやって + V(di chuyển) + か → trả lời: N(phương tiện) + で + 行きます／来ます／帰ります', 'Hỏi và trả lời về phương tiện di chuyển', NULL, NULL, NULL, '{}', NULL, 35, 'なにで／どうやって [V di chuyển] か', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('91129479-6604-4375-83c5-3eae5e34ece4', 'N5', 'N(chỉ người) と Vます', 'Làm gì cùng ai', 'と = với, cùng', 'N(người) + と + V ます', 'Chỉ người cùng thực hiện hành động', NULL, NULL, NULL, '{}', NULL, 35, 'N(chỉ người) と Vます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('eda5d119-e29d-44da-bb6e-8740efa60164', 'N5', 'N を Vます', 'Làm việc gì (tân ngữ trực tiếp)', 'を đánh dấu tân ngữ trực tiếp của động từ', 'N(tân ngữ) + を + V ます', 'Chỉ đối tượng trực tiếp chịu tác động của hành động', NULL, NULL, NULL, '{}', NULL, 35, 'N を Vます', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('e411a324-a0d8-427d-8fb4-e6a30d222896', '1a9743c4-3fc3-4410-9acf-935b790ccd34', 1, 'Hiện tại/Tương lai: V ます (khẳng định) / V ません (phủ định)', 'Vます (+) ／ Vません (-)', 'Diễn tả việc sẽ làm hoặc thói quen ở hiện tại/tương lai', NULL, 34, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('bd489c2f-d18a-48a6-a2a3-89db14a46b99', '1a9743c4-3fc3-4410-9acf-935b790ccd34', 2, 'Quá khứ: V ました (khẳng định) / V ませんでした (phủ định)', 'Vました (+) ／ Vませんでした (-)', 'Diễn tả việc đã làm hoặc đã không làm trong quá khứ', NULL, 34, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3fe1c8c3-c46f-4a3b-a577-b8ff116c9617', NULL, 1, 'standard', 'もしもし、今何時ですか。', 'Alo, bây giờ là mấy giờ rồi?', 'もしもし、今＿＿＿ですか。', '何時', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type, review_status, corrected_text, correction_note) values ('3fe1c8c3-c46f-4a3b-a577-b8ff116c9617', NULL, 2, 'standard', '今、午前3時半です。', 'Bây giờ là 3 giờ rưỡi chiều.', '今、午前3＿＿＿です。', '時半', 'pdf', 'needs_review', '今、午後3時半です。(hoặc dịch lại: Bây giờ là 3 giờ rưỡi SÁNG.)', 'PDF gốc dùng 午前 (buổi sáng/AM) nhưng bản dịch tiếng Việt ghi "chiều" (PM) — mâu thuẫn giữa tiếng Nhật và bản dịch, khả năng là lỗi đánh máy trong tài liệu gốc (nên là 午後, hoặc bản dịch phải là "sáng").');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3fe1c8c3-c46f-4a3b-a577-b8ff116c9617', NULL, 3, 'daily', '今、午後7時です。', 'Bây giờ là 7 giờ tối.', '今、午後＿＿＿です。', '7時', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('57dc0af9-fcde-430e-abe4-f3aef7bcce27', NULL, 1, 'standard', '今日は何曜日ですか。', 'Hôm nay là thứ mấy?', '今日は＿＿＿ですか。', '何曜日', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('57dc0af9-fcde-430e-abe4-f3aef7bcce27', NULL, 2, 'standard', '月曜日です。', 'Là thứ Hai.', '＿＿＿です。', '月曜日', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('57dc0af9-fcde-430e-abe4-f3aef7bcce27', NULL, 3, 'daily', '明日は金曜日です。', 'Ngày mai là thứ Sáu.', '明日は＿＿＿です。', '金曜日', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1a9743c4-3fc3-4410-9acf-935b790ccd34', 'e411a324-a0d8-427d-8fb4-e6a30d222896', 1, 'standard', '明日、べんきょうしますか。', 'Ngày mai cậu học bài không?', '明日、べんきょうし＿＿＿か。', 'ます', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1a9743c4-3fc3-4410-9acf-935b790ccd34', 'e411a324-a0d8-427d-8fb4-e6a30d222896', 2, 'standard', '今日べんきょうしません。', 'Hôm nay tôi không học bài.', '今日べんきょうし＿＿＿。', 'ません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1a9743c4-3fc3-4410-9acf-935b790ccd34', 'e411a324-a0d8-427d-8fb4-e6a30d222896', 3, 'daily', 'あした、はたらきます。', 'Ngày mai tôi đi làm.', 'あした、はたらき＿＿＿。', 'ます', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1a9743c4-3fc3-4410-9acf-935b790ccd34', 'bd489c2f-d18a-48a6-a2a3-89db14a46b99', 1, 'standard', '昨日べんきょうしました。', 'Hôm qua tôi đã học bài.', '昨日べんきょうし＿＿＿。', 'ました', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1a9743c4-3fc3-4410-9acf-935b790ccd34', 'bd489c2f-d18a-48a6-a2a3-89db14a46b99', 2, 'standard', 'おとといもべんきょうしませんでした。', 'Ngày hôm kia tôi cũng đã không học bài.', 'おとといもべんきょうし＿＿＿。', 'ませんでした', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1a9743c4-3fc3-4410-9acf-935b790ccd34', 'bd489c2f-d18a-48a6-a2a3-89db14a46b99', 3, 'daily', 'きのう、はたらきませんでした。', 'Hôm qua tôi đã không đi làm.', 'きのう、はたらき＿＿＿。', 'ませんでした', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('98416a06-995f-4ef8-b1fd-026aa40d6abd', NULL, 1, 'standard', '今朝、6時半に起きました。', 'Sáng nay tôi thức dậy vào lúc 6 rưỡi.', '今朝、6時半＿＿＿起きました。', 'に', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('98416a06-995f-4ef8-b1fd-026aa40d6abd', NULL, 2, 'standard', '「さくら日本語学校」は午後4時半に終わりました。', 'Trường Nhật ngữ Sakura đóng cửa lúc 4 rưỡi chiều.', '「さくら日本語学校」は午後4時半＿＿＿終わりました。', 'に', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('98416a06-995f-4ef8-b1fd-026aa40d6abd', NULL, 3, 'daily', '7時にあさごはんをたべます。', 'Tôi ăn sáng lúc 7 giờ.', '7時＿＿＿あさごはんをたべます。', 'に', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c3ef7665-38bb-4b7c-83e5-a5c51cef1cd6', NULL, 1, 'standard', '毎日、午前7時から午後8時半まで働きます。', 'Hằng ngày, tôi làm việc từ 7 giờ sáng đến 8 rưỡi tối.', '毎日、午前7時＿＿＿午後8時半＿＿＿働きます。', 'から／まで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c3ef7665-38bb-4b7c-83e5-a5c51cef1cd6', NULL, 2, 'standard', '月曜日から金曜日まで勉強します。', 'Tôi học từ thứ Hai đến thứ Sáu.', '月曜日＿＿＿金曜日＿＿＿勉強します。', 'から／まで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c3ef7665-38bb-4b7c-83e5-a5c51cef1cd6', NULL, 3, 'daily', '9時から5時まではたらきます。', 'Tôi làm việc từ 9 giờ đến 5 giờ.', '9時＿＿＿5時＿＿＿はたらきます。', 'から／まで', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2b3c8291-13bd-434d-a92b-3dbfa33f4fa3', NULL, 1, 'standard', '今年は何年ですか。', 'Năm nay là năm bao nhiêu?', '今年は＿＿＿ですか。', '何年', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2b3c8291-13bd-434d-a92b-3dbfa33f4fa3', NULL, 2, 'standard', '2019年です。', 'Là năm 2019.', '2019＿＿＿です。', '年', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2b3c8291-13bd-434d-a92b-3dbfa33f4fa3', NULL, 3, 'standard', '今日は8月17日です。', 'Hôm nay là ngày 17 tháng 8.', '今日は8月17＿＿＿です。', '日', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2c69e6c2-7c84-4530-9d68-3396cb7c6d5c', NULL, 1, 'standard', '明日、スーパーへ行きます。', 'Ngày mai tôi sẽ đi siêu thị.', '明日、スーパー＿＿＿行きます。', 'へ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2c69e6c2-7c84-4530-9d68-3396cb7c6d5c', NULL, 2, 'standard', 'ハノイへ来ました。', 'Tôi đã đến Hà Nội.', 'ハノイ＿＿＿来ました。', 'へ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2c69e6c2-7c84-4530-9d68-3396cb7c6d5c', NULL, 3, 'standard', '日曜日、午前10時に実家へ帰りました。', 'Chủ nhật, tôi đã về nhà lúc 10 giờ sáng.', '日曜日、午前10時に実家＿＿＿帰りました。', 'へ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('001cd48a-2590-4a3c-9bf7-5b84ad1c356f', NULL, 1, 'standard', '明日、どこへ行きますか。', 'Ngày mai bạn có đi đâu không?', '明日、＿＿＿へ行きますか。', 'どこ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('001cd48a-2590-4a3c-9bf7-5b84ad1c356f', NULL, 2, 'standard', 'どこもいきません。', 'Tôi không đi đâu cả.', '＿＿＿もいきません。', 'どこ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('001cd48a-2590-4a3c-9bf7-5b84ad1c356f', NULL, 3, 'daily', '今日はどこもいきません。', 'Hôm nay tôi không đi đâu cả.', '今日は＿＿＿もいきません。', 'どこ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4f4df88e-135b-448b-bc56-9738de140aa7', NULL, 1, 'standard', 'なにで東京へ来ましたか。', 'Bạn đã đến Tokyo bằng phương tiện gì?', '＿＿＿東京へ来ましたか。', 'なにで', 'pdf');
