insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('4f4df88e-135b-448b-bc56-9738de140aa7', NULL, 'choose_connection', 'Cách nối đúng của mẫu "なにで／どうやって [V di chuyển] か" (Hỏi đi bằng phương tiện gì) là gì?', '(Địa điểm) + へ／に + 行きます(đi)／来ます(đến)／帰ります(về)', '① Số đếm + 時 (giờ) ② Số đếm + ふん／ぷん (phút) ③ 半(rưỡi)／午前(sáng)／午後(chiều)／夜(tối) + giờ', 'N(tân ngữ) + を + V ます', 'なにで + V(di chuyển) + か ／ どうやって + V(di chuyển) + か → trả lời: N(phương tiện) + で + 行きます／来ます／帰ります', 'なにで + V(di chuyển) + か ／ どうやって + V(di chuyển) + か → trả lời: N(phương tiện) + で + 行きます／来ます／帰ります', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('91129479-6604-4375-83c5-3eae5e34ece4', NULL, 'fill_blank', 'Điền vào chỗ trống: 昨日、友達＿＿＿映画を見に行きました。', NULL, NULL, NULL, NULL, 'と', 'generated');
