insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('91129479-6604-4375-83c5-3eae5e34ece4', NULL, 'choose_connection', 'Cách nối đúng của mẫu "N(chỉ người) と Vます" (Làm gì cùng ai) là gì?', 'N(người) + と + V ます', 'どこ(へ) + も + いきません', 'Vました (+) ／ Vませんでした (-)', 'なにで + V(di chuyển) + か ／ どうやって + V(di chuyển) + か → trả lời: N(phương tiện) + で + 行きます／来ます／帰ります', 'N(người) + と + V ます', 'generated');
